.version 8.8
.target sm_103
.address_size 64
.visible .entry vector_add(
 .param .u64 pa, .param .u64 pb, .param .u64 pc, .param .u32 pn
) {
 .reg .pred %p;
 .reg .u32 %r<5>;
 .reg .u64 %rd<8>;
 .reg .f32 %f<3>;
 ld.param.u64 %rd0, [pa];
 ld.param.u64 %rd1, [pb];
 ld.param.u64 %rd2, [pc];
 ld.param.u32 %r4, [pn];
 cvta.to.global.u64 %rd0, %rd0;
 cvta.to.global.u64 %rd1, %rd1;
 cvta.to.global.u64 %rd2, %rd2;
 mov.u32 %r0, %tid.x;
 mov.u32 %r1, %ctaid.x;
 mov.u32 %r2, %ntid.x;
 mad.lo.u32 %r3, %r1, %r2, %r0;
 setp.ge.u32 %p, %r3, %r4;
 @%p bra DONE;
 mul.wide.u32 %rd3, %r3, 4;
 add.u64 %rd4, %rd0, %rd3;
 add.u64 %rd5, %rd1, %rd3;
 add.u64 %rd6, %rd2, %rd3;
 ld.global.f32 %f0, [%rd4];
 ld.global.f32 %f1, [%rd5];
 add.f32 %f2, %f0, %f1;
 st.global.f32 [%rd6], %f2;
DONE:
 ret;
}

.version 8.8
.target sm_103
.address_size 64
.visible .entry reduce256(.param .u64 pa, .param .u64 pout) {
 .reg .pred %p;
 .reg .u32 %r<6>;
 .reg .u64 %rd<4>;
 .reg .f32 %f<2>;
 .shared .align 4 .b8 scratch[1024];
 ld.param.u64 %rd0, [pa];
 ld.param.u64 %rd1, [pout];
 cvta.to.global.u64 %rd0, %rd0;
 cvta.to.global.u64 %rd1, %rd1;
 mov.u32 %r0, %tid.x;
 mul.wide.u32 %rd2, %r0, 4;
 add.u64 %rd3, %rd0, %rd2;
 ld.global.f32 %f0, [%rd3];
 mov.u32 %r1, scratch;
 shl.b32 %r2, %r0, 2;
 add.u32 %r2, %r1, %r2;
 st.shared.f32 [%r2], %f0;
 bar.sync 0;
 mov.u32 %r3, 128;
LOOP:
 setp.ge.u32 %p, %r0, %r3;
 @%p bra WAIT;
 shl.b32 %r4, %r3, 2;
 add.u32 %r5, %r2, %r4;
 ld.shared.f32 %f1, [%r5];
 add.f32 %f0, %f0, %f1;
 st.shared.f32 [%r2], %f0;
WAIT:
 bar.sync 0;
 shr.u32 %r3, %r3, 1;
 setp.ne.u32 %p, %r3, 0;
 @%p bra LOOP;
 setp.ne.u32 %p, %r0, 0;
 @%p bra DONE;
 st.global.f32 [%rd1], %f0;
DONE:
 ret;
}

.version 8.8
.target sm_103
.address_size 64
.visible .entry matmul16(.param .u64 pa, .param .u64 pb, .param .u64 pc) {
 .reg .pred %p;
 .reg .u32 %r<9>;
 .reg .u64 %rd<8>;
 .reg .f32 %f<3>;
 ld.param.u64 %rd0, [pa];
 ld.param.u64 %rd1, [pb];
 ld.param.u64 %rd2, [pc];
 cvta.to.global.u64 %rd0, %rd0;
 cvta.to.global.u64 %rd1, %rd1;
 cvta.to.global.u64 %rd2, %rd2;
 mov.u32 %r0, %tid.x;
 shr.u32 %r1, %r0, 4;
 and.b32 %r2, %r0, 15;
 mov.u32 %r3, 0;
 mov.f32 %f2, 0f00000000;
LOOP:
 mad.lo.u32 %r4, %r1, 16, %r3;
 mad.lo.u32 %r5, %r3, 16, %r2;
 mul.wide.u32 %rd3, %r4, 4;
 mul.wide.u32 %rd4, %r5, 4;
 add.u64 %rd5, %rd0, %rd3;
 add.u64 %rd6, %rd1, %rd4;
 ld.global.f32 %f0, [%rd5];
 ld.global.f32 %f1, [%rd6];
 fma.rn.f32 %f2, %f0, %f1, %f2;
 add.u32 %r3, %r3, 1;
 setp.lt.u32 %p, %r3, 16;
 @%p bra LOOP;
 mul.wide.u32 %rd3, %r0, 4;
 add.u64 %rd7, %rd2, %rd3;
 st.global.f32 [%rd7], %f2;
 ret;
}
